// src/components/ROI/tabs/ProjectStatusTab.js
import React, { useEffect, useMemo, useState } from "react";
import { useOutletContext } from "react-router-dom";
import axios from "axios";

export default function ProjectStatusTab() {
  const { intakeNumber } = useOutletContext?.() || {};

  // --- Compact UI helpers ---
  const labelCls = "text-sm text-gray-700";
  const inputCls = "border rounded px-2 py-1 text-sm";
  const selectCls = "border rounded px-2 py-1 text-sm";
  const areaCls = "border rounded px-2 py-1 text-sm";
  const sectionWrap = "border rounded-lg p-3 mb-3 bg-white";
  const sectionTitle =
    "tab-section tab-section-yellow !bg-yellow-50 !text-gray-800 !py-2 !px-3 !rounded mb-2";
  const grid2 = "grid grid-cols-1 md:grid-cols-2 gap-3";
  const grid3 = "grid grid-cols-1 md:grid-cols-3 gap-3";

  // options
  const deliveryModelOptions = ["FP", "T&M"];
  const timelineOptions = ["Yes", "No"];
  const projectStatusOptions = [
    "Confirmed - Not Started",
    "Active - Discovery/pre kickoff",
    "Active - Project Kick Off",
    "Active - BRD/SRD",
    "Active - Solution / Design",
    "Active - Construction",
    "Active - DIT",
    "Active - SIT",
    "Active - UAT",
    "Project On Hold",
    "Project Completed / Closed",
    "Project Cancelled",
    "TBD (Status not known)",
  ];
  const estimateStatusOptions = ["Sent", "Automation-OOS"];
  const funcAutomationOptions = ["yes", "no"];
  const automationStatusOptions = [
    { label: "---ACTIVE---", disabled: true },
    { label: "Automation Intake/assessment" },
    { label: "Automation Work NOT Started" },
    { label: "SRD/BRD Phase" },
    { label: "Automation Test Planning" },
    { label: "Test Design - ConformIQ" },
    {
      label:
        "Scripting & Dry Run - Robot / Selenium / UFT / SOA / Scriptless",
    },
    { label: "Test Execution  - DIT" },
    { label: "Test Execution  - SIT" },
    { label: "Test Execution  - UAT" },
    { label: "Test Execution  - Support" },
    { label: "Test Support (Post execution)" },
    { label: "Automation Closure Activities" },
    { label: "KT Tasks" },
    { label: "Automated Test Design - QA Self" },
    { label: "Automated Test Execution - QA Self" },
    { label: "---DORMANT / CLOSED---", disabled: true },
    { label: "Pending Go ahead for Execution" },
    { label: "Auto. Work On Hold" },
    { label: "Auto. Work Cancelled" },
    { label: "Auto. Work Not Started" },
    { label: "Auto. Work Completed" },
    { label: "Test Design - Support" },
  ];

  // --- State (prefilled from /api/projects/:intakeNumber + /api/resourcefetch) ---
  const [resources, setResources] = useState([]); // dropdown options from /api/resourcefetch

  const [details, setDetails] = useState({
    deliveryModel: "",
    timelinesAvailable: "",
    projectCurrentStatus: "",
  });

  const [stakeholders, setStakeholders] = useState({
    qaManager: "",
    functionalQeLead: "",
    funcSme: "",
    automationLeadOrQeLead: "",
    offshoreLead: "",
    fteOrAutomationArchitect: "",
    itPm: "",
  });

  const [dates, setDates] = useState({
    autoStartDate: "",
    autoEndDate: "",
    implementationDate: "",
  });

  const [estimation, setEstimation] = useState({
    estimateDueDate: "",
    estimateSubmittedOn: "",
    estimateStatusOrOOS: "",
    assignedToOrDoneBy: "",
    estimateReviewedBy: "",
    funcAutomation: "",
    reasonIfOOSorNoNew: "",
	qaCostWithoutAuto: "",   // = manual_cost
	qaCostWithAuto: "",      // = manual_cost + automation_cost
	automationCost: "",      // hidden field = automation_cost
    targetedMinSavings: "", // computed & uneditable
  });

  const [automationStatus, setAutomationStatus] = useState({
    currentStatus: "",
    comments: "",
  });

  const [deliverables, setDeliverables] = useState({
    testPlanLTW: false,
    qaChecklistFollowed: false,
    tcUpdateInALMConfluence: false,
    gitUpdate: false,
    dsr: false,
    leSentToPMMonthly: false,
    masterRegUpdatedALM: false,
    masterDashboardUpdated: false,
    releaseHandover: false,
    projectClosureReport: false,
    roiRealizedIn: "", // calendar (ROIMonth)
    // (No ROI Reason was not mapped in your step 3 update list, so leaving it out of updates)
    qeTransformed: false,
    shiftLeftFollowed: false,
  });

  // banners
  const [saving, setSaving] = useState(false);
  const [saveErr, setSaveErr] = useState("");
  const [saveOk, setSaveOk] = useState("");

  // snapshot for dirty tracking
  const [snapshot, setSnapshot] = useState(null);

  // fetch resources + project details
  useEffect(() => {
    let mounted = true;
    const load = async () => {
      try {
		const [resProj, resRes, resDel] = await Promise.all([
		  axios.get(`http://localhost:5000/api/projects/${intakeNumber}`),
		  axios.get("http://localhost:5000/api/resourcefetch"),
		  axios.get(`http://localhost:5000/api/automationdeliverables/${intakeNumber}`) // <— NEW ENDPOINT YOU SHOULD EXPOSE
		]);

        if (!mounted) return;

        const p = resProj.data || {};
        const names = Array.isArray(resRes.data?.resources)
          ? resRes.data.resources
          : Array.isArray(resRes.data)
          ? resRes.data
          : [];

        setResources(names);

        setDetails({
          deliveryModel: p.DeliveryModel || "",
          timelinesAvailable: p.TimeLineAvailable || "",
          projectCurrentStatus: p.project_status || "",
        });

        setStakeholders({
          qaManager: p.QAManager || "",
          functionalQeLead: p.functional_qe_lead || "",
          funcSme: p.FuncSME || "",
          automationLeadOrQeLead: p.automation_qe_lead || "",
          offshoreLead: p.OffshoreLead || "",
          fteOrAutomationArchitect: p.FTE_Architect || "",
          itPm: p.ITPM || "",
        });

        setDates({
          autoStartDate: p.AutoWorkStartDate || "",
          autoEndDate: p.AutoWorkEndDate || "",
          implementationDate: p.ImplementationDate || "", // expect backend join; else stays blank
        });

		const manual = p.manual_cost ?? "";
		const autoCost = p.automation_cost ?? "";
		const qaCostWithout = manual; // "Without" mirrors manual_cost
		const qaCostWith =
		  manual !== "" || autoCost !== ""
		    ? Number(manual || 0) + Number(autoCost || 0)
		    : "";

		const minSavings =
		  qaCostWithout !== "" && qaCostWith !== ""
		    ? Number(qaCostWithout || 0) - Number(qaCostWith || 0)
		    : p.PSEMinSavings || "";

        setEstimation({
          estimateDueDate: p.AutoEstimateDueDate || "",
          estimateSubmittedOn: p.AutoEstimateSubmittedOn || "",
          estimateStatusOrOOS: p.AutoEstimateStatus || "",
          assignedToOrDoneBy: p.EstimateAssignedTo || "",
          estimateReviewedBy: p.EstimateReviewedBy || "",
          funcAutomation: p.FuncAutomationScope || "",
          reasonIfOOSorNoNew: p.AutoOOSReason || "",
		  qaCostWithoutAuto: qaCostWithout,             // manual_cost
		  qaCostWithAuto: qaCostWith,                   // manual_cost + automation_cost
		  automationCost: autoCost,                     // NEW
          targetedMinSavings: minSavings,
        });

        setAutomationStatus({
          currentStatus: p.AutomationStatus || "",
          comments: p.Comments || "",
        });

		const d = resDel?.data || {}; // expect a dict like {"AutomationTestPlan":"YES", ...} or empty {}
		setDeliverables({
		  testPlanLTW: !!d.AutomationTestPlan,
		  qaChecklistFollowed: !!d.Checklist,
		  tcUpdateInALMConfluence: !!d.ALMupdate,
		  gitUpdate: !!d.GITUpdate,
		  dsr: !!d.DSR, // (optional; not part of your new list but safe to keep)
		  leSentToPMMonthly: !!d.LESubmitted,
		  masterRegUpdatedALM: !!d.RegressionTestLab,
		  masterDashboardUpdated: !!d.DashboardMetric,
		  releaseHandover: !!d.ReleaseHandover,
		  projectClosureReport: !!d.ProjectClosure,
		  roiRealizedIn: d.ROIMonth || "", // untouched; out of current change list
		  qeTransformed: !!d.QETransformed,
		  shiftLeftFollowed: !!d.ShiftLeft,
		});

        // snapshot for dirty tracking
        setSnapshot({
          details: {
            deliveryModel: p.DeliveryModel || "",
            timelinesAvailable: p.TimeLineAvailable || "",
            projectCurrentStatus: p.project_status || "",
          },
          stakeholders: {
            qaManager: p.QAManager || "",
            functionalQeLead: p.functional_qe_lead || "",
            funcSme: p.FuncSME || "",
            automationLeadOrQeLead: p.automation_qe_lead || "",
            offshoreLead: p.OffshoreLead || "",
            fteOrAutomationArchitect: p.FTE_Architect || "",
            itPm: p.ITPM || "",
          },
          dates: {
            autoStartDate: p.AutoWorkStartDate || "",
            autoEndDate: p.AutoWorkEndDate || "",
            implementationDate: p.ImplementationDate || "",
          },
          estimation: {
            estimateDueDate: p.AutoEstimateDueDate || "",
            estimateSubmittedOn: p.AutoEstimateSubmittedOn || "",
            estimateStatusOrOOS: p.AutoEstimateStatus || "",
            assignedToOrDoneBy: p.EstimateAssignedTo || "",
            estimateReviewedBy: p.EstimateReviewedBy || "",
            funcAutomation: p.FuncAutomationScope || "",
            reasonIfOOSorNoNew: p.AutoOOSReason || "",
            qaCostWithoutAuto: qaCostWithout,
            qaCostWithAuto: qaCostWith,
            targetedMinSavings: minSavings,
          },
          automationStatus: {
            currentStatus: p.AutomationStatus || "",
            comments: p.Comments || "",
          },
         
		   deliverables: {
			testPlanLTW: !!d.AutomationTestPlan,
			    qaChecklistFollowed: !!d.Checklist,
			    tcUpdateInALMConfluence: !!d.ALMupdate,
			    gitUpdate: !!d.GITUpdate,
			    dsr: !!d.DSR,
			    leSentToPMMonthly: !!d.LESubmitted,
			    masterRegUpdatedALM: !!d.RegressionTestLab,
			    masterDashboardUpdated: !!d.DashboardMetric,
			    releaseHandover: !!d.ReleaseHandover,
			    projectClosureReport: !!d.ProjectClosure,
			    roiRealizedIn: d.ROIMonth || "",
			    qeTransformed: !!d.QETransformed,
			    shiftLeftFollowed: !!d.ShiftLeft,
          },
		  
        });
      } catch (e) {
        console.error("Failed to load project status data", e);
      }
    };
    load();
    return () => {
      mounted = false;
    };
  }, [intakeNumber]);

  // compute targeted minimum savings UI (uneditable)
  useEffect(() => {
    const qaCostWithout = Number(estimation.qaCostWithoutAuto || 0);
    const qaCostWith = Number(estimation.qaCostWithAuto || 0);
    const next = qaCostWithout - qaCostWith;
    if (String(next) !== String(estimation.targetedMinSavings)) {
      setEstimation((s) => ({ ...s, targetedMinSavings: next }));
    }
  }, [estimation.qaCostWithoutAuto, estimation.qaCostWithAuto]);

  // Dirty tracking (button disabled if nothing changed)
  const dirty = useMemo(() => {
    if (!snapshot) return false;
    const now = {
      details,
      stakeholders,
      dates,
      estimation,
      automationStatus,
      deliverables,
    };
    return JSON.stringify(now) !== JSON.stringify(snapshot);
  }, [
    details,
    stakeholders,
    dates,
    estimation,
    automationStatus,
    deliverables,
    snapshot,
  ]);

  const resetBanners = () => {
    setSaveErr("");
    setSaveOk("");
  };

  const onSaveAll = async () => {
    resetBanners();
    if (!dirty) return;
    setSaving(true);
    try {
      const updates = [];

      // helpers to conditionally push updates if changed
      const pushIfChanged = (table, column, newVal, oldVal) => {
        if (String(newVal ?? "") !== String(oldVal ?? "")) {
          updates.push({ table, column, value: newVal });
        }
      };

      // details -> projects
	  
	  
      pushIfChanged(
        "projects",
        "DeliveryModel",
        details.deliveryModel,
        snapshot.details.deliveryModel
      );
      pushIfChanged(
        "projects",
        "TimeLineAvailable",
        details.timelinesAvailable,
        snapshot.details.timelinesAvailable
      );
      pushIfChanged(
        "projects",
        "project_status",
        details.projectCurrentStatus,
        snapshot.details.projectCurrentStatus
      );

      // stakeholders -> projects
      pushIfChanged(
        "projects",
        "QAManager",
        stakeholders.qaManager,
        snapshot.stakeholders.qaManager
      );
      pushIfChanged(
        "projects",
        "functional_qe_lead",
        stakeholders.functionalQeLead,
        snapshot.stakeholders.functionalQeLead
      );
      pushIfChanged(
        "projects",
        "FuncSME",
        stakeholders.funcSme,
        snapshot.stakeholders.funcSme
      );
      pushIfChanged(
        "projects",
        "automation_qe_lead",
        stakeholders.automationLeadOrQeLead,
        snapshot.stakeholders.automationLeadOrQeLead
      );
      pushIfChanged(
        "projects",
        "OffshoreLead",
        stakeholders.offshoreLead,
        snapshot.stakeholders.offshoreLead
      );
      pushIfChanged(
        "projects",
        "FTE_Architect",
        stakeholders.fteOrAutomationArchitect,
        snapshot.stakeholders.fteOrAutomationArchitect
      );
      pushIfChanged(
        "projects",
        "ITPM",
        stakeholders.itPm,
        snapshot.stakeholders.itPm
      );

      // dates -> projects / projects_timeline
      pushIfChanged(
        "projects",
        "AutoWorkStartDate",
        dates.autoStartDate,
        snapshot.dates.autoStartDate
      );
      pushIfChanged(
        "projects",
        "AutoWorkEndDate",
        dates.autoEndDate,
        snapshot.dates.autoEndDate
      );
      pushIfChanged(
        "projects_timeline",
        "ImplementationDate",
        dates.implementationDate,
        snapshot.dates.implementationDate
      );

      // estimation -> projects
      pushIfChanged(
        "projects",
        "AutoEstimateDueDate",
        estimation.estimateDueDate,
        snapshot.estimation.estimateDueDate
      );
      pushIfChanged(
        "projects",
        "AutoEstimateSubmittedOn",
        estimation.estimateSubmittedOn,
        snapshot.estimation.estimateSubmittedOn
      );
      pushIfChanged(
        "projects",
        "AutoEstimateStatus",
        estimation.estimateStatusOrOOS,
        snapshot.estimation.estimateStatusOrOOS
      );
      pushIfChanged(
        "projects",
        "EstimateAssignedTo",
        estimation.assignedToOrDoneBy,
        snapshot.estimation.assignedToOrDoneBy
      );
      pushIfChanged(
        "projects",
        "EstimateReviewedBy",
        estimation.estimateReviewedBy,
        snapshot.estimation.estimateReviewedBy
      );
      pushIfChanged(
        "projects",
        "FuncAutomationScope",
        estimation.funcAutomation,
        snapshot.estimation.funcAutomation
      );
      // only editable when funcAutomation === 'no'
      if (estimation.funcAutomation === "no") {
        pushIfChanged(
          "projects",
          "AutoOOSReason",
          estimation.reasonIfOOSorNoNew,
          snapshot.estimation.reasonIfOOSorNoNew
        );
      }
	  pushIfChanged(
	    "projects",
	    "manual_cost",
	    estimation.qaCostWithoutAuto,
	    snapshot.estimation.qaCostWithoutAuto
	  );
	  pushIfChanged(
	    "projects",
	    "automation_cost",
	    estimation.automationCost,   // <-- derived as (With - Without)
	    snapshot.estimation.automationCost
	  );
	  
      // computed & uneditable but still persisted
      pushIfChanged(
        "projects",
        "PSEMinSavings",
        estimation.targetedMinSavings,
        snapshot.estimation.targetedMinSavings
      );

      // automation status -> projects
      pushIfChanged(
        "projects",
        "AutomationStatus",
        automationStatus.currentStatus,
        snapshot.automationStatus.currentStatus
      );
      pushIfChanged(
        "projects",
        "Comments",
        automationStatus.comments,
        snapshot.automationStatus.comments
      );

	  
      // deliverables -> automationdeliverables
      pushIfChanged(
        "automationdeliverables",
        "AutomationTestPlan",
        deliverables.testPlanLTW ? 1 : 0,
        snapshot.deliverables.testPlanLTW ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "Checklist",
        deliverables.qaChecklistFollowed ? 1 : 0,
        snapshot.deliverables.qaChecklistFollowed ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "ALMupdate",
        deliverables.tcUpdateInALMConfluence ? 1 : 0,
        snapshot.deliverables.tcUpdateInALMConfluence ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "GITUpdate",
        deliverables.gitUpdate ? 1 : 0,
        snapshot.deliverables.gitUpdate ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "DSR",
        deliverables.dsr ? 1 : 0,
        snapshot.deliverables.dsr ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "LESubmitted",
        deliverables.leSentToPMMonthly ? 1 : 0,
        snapshot.deliverables.leSentToPMMonthly ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "RegressionTestLab",
        deliverables.masterRegUpdatedALM ? 1 : 0,
        snapshot.deliverables.masterRegUpdatedALM ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "DashboardMetric",
        deliverables.masterDashboardUpdated ? 1 : 0,
        snapshot.deliverables.masterDashboardUpdated ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "ReleaseHandover",
        deliverables.releaseHandover ? 1 : 0,
        snapshot.deliverables.releaseHandover ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "ProjectClosure",
        deliverables.projectClosureReport ? 1 : 0,
        snapshot.deliverables.projectClosureReport ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "ROIMonth",
        deliverables.roiRealizedIn,
        snapshot.deliverables.roiRealizedIn
      );
      pushIfChanged(
        "automationdeliverables",
        "QETransformed",
        deliverables.qeTransformed ? 1 : 0,
        snapshot.deliverables.qeTransformed ? 1 : 0
      );
      pushIfChanged(
        "automationdeliverables",
        "ShiftLeft",
        deliverables.shiftLeftFollowed ? 1 : 0,
        snapshot.deliverables.shiftLeftFollowed ? 1 : 0
      );

      if (updates.length === 0) {
        setSaving(false);
        return;
      }

      const payload = { intake_number: intakeNumber, updates };
      const resp = await axios.post(
        "http://localhost:5000/api/projectmasterupdate",
        payload
      );

      if (resp.status === 200 && resp.data?.ok) {
        setSaveOk("Saved successfully.");
        // refresh snapshot
        setSnapshot({
          details,
          stakeholders,
          dates,
          estimation,
          automationStatus,
          deliverables,
        });
      } else {
        setSaveErr(resp.data?.error || "Update failed.");
      }
    } catch (e) {
      console.error("Save failed", e);
      setSaveErr("Save failed. See console for details.");
    } finally {
      setSaving(false);
    }
  };

  // small field builders
  const Text = ({ label, value, onChange, placeholder, type = "text", disabled = false }) => (
    <div className="flex flex-col">
      <span className={labelCls}>{label}</span>
      <input
        className={inputCls}
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
      />
    </div>
  );

  const Select = ({ label, value, onChange, options, disabled = false }) => (
    <div className="flex flex-col">
      <span className={labelCls}>{label}</span>
      <select
        className={selectCls}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
      >
        <option value="">-- Select --</option>
        {options.map((o) =>
          typeof o === "string" ? (
            <option key={o} value={o}>
              {o}
            </option>
          ) : (
            <option key={o.label} value={o.label} disabled={!!o.disabled}>
              {o.label}
            </option>
          )
        )}
      </select>
    </div>
  );

  const Area = ({ label, value, onChange, placeholder, disabled = false }) => (
    <div className="flex flex-col md:col-span-2">
      <span className={labelCls}>{label}</span>
      <textarea
        className={areaCls}
        rows={3}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
      />
    </div>
  );

  const Check = ({ label, value, onChange }) => (
    <label className="inline-flex items-center gap-2 text-sm">
      <input
        type="checkbox"
        checked={!!value}
        onChange={(e) => onChange(e.target.checked)}
      />
      <span className="text-gray-700">{label}</span>
    </label>
  );

  return (
    <div className="tab-wrap">
      {/* Save All top bar */}
      <div className="flex items-center justify-between mb-3">
        <div className="text-sm text-gray-600">
          {saveOk && <span className="text-green-700">{saveOk}</span>}
          {saveErr && <span className="text-red-700">{saveErr}</span>}
        </div>
        <button
          className="btn-red"
          onClick={onSaveAll}
          disabled={!dirty || saving}
          title={!dirty ? "No changes to save" : "Save updates"}
        >
          {saving ? "Saving..." : "<Save All>"}
        </button>
      </div>

      {/* 1) Project Details */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Details</div>
        <div className={grid3}>
          <Select
            label="Delivery model"
            value={details.deliveryModel}
            onChange={(v) => setDetails((s) => ({ ...s, deliveryModel: v }))}
            options={deliveryModelOptions}
          />
          <Select
            label="Project Timelines Available ?"
            value={details.timelinesAvailable}
            onChange={(v) => setDetails((s) => ({ ...s, timelinesAvailable: v }))}
            options={timelineOptions}
          />
          <Select
            label="Project Current Status"
            value={details.projectCurrentStatus}
            onChange={(v) => setDetails((s) => ({ ...s, projectCurrentStatus: v }))}
            options={projectStatusOptions}
          />
        </div>
      </div>

      {/* 2) Project Stakeholders */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Stakeholders</div>
        <div className={grid3}>
          <Text
            label="QA Manager"
            value={stakeholders.qaManager}
            onChange={(v) => setStakeholders((s) => ({ ...s, qaManager: v }))}
            placeholder="Name"
          />
          <Select
            label="Functional_qe_lead"
            value={stakeholders.functionalQeLead}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, functionalQeLead: v }))
            }
            options={resources}
          />
          <Select
            label="Func. SME"
            value={stakeholders.funcSme}
            onChange={(v) => setStakeholders((s) => ({ ...s, funcSme: v }))}
            options={resources}
          />
          <Select
            label="Automation Lead (old) / QE lead (new)"
            value={stakeholders.automationLeadOrQeLead}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, automationLeadOrQeLead: v }))
            }
            options={resources}
          />
          <Select
            label="Offshore Lead Resource"
            value={stakeholders.offshoreLead}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, offshoreLead: v }))
            }
            options={resources}
          />
          <Select
            label="FTE (old) / Automation Architect (new)"
            value={stakeholders.fteOrAutomationArchitect}
            onChange={(v) =>
              setStakeholders((s) => ({
                ...s,
                fteOrAutomationArchitect: v,
              }))
            }
            options={resources}
          />
          <Text
            label="IT PM"
            value={stakeholders.itPm}
            onChange={(v) => setStakeholders((s) => ({ ...s, itPm: v }))}
            placeholder="Name"
          />
        </div>
      </div>

      {/* 3) Project Dates */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Dates</div>
        <div className={grid3}>
          <Text
            label="Auto. Work Start Date"
            type="date"
            value={dates.autoStartDate}
            onChange={(v) => setDates((s) => ({ ...s, autoStartDate: v }))}
          />
          <Text
            label="Auto. Work End Date"
            type="date"
            value={dates.autoEndDate}
            onChange={(v) => setDates((s) => ({ ...s, autoEndDate: v }))}
          />
          <Text
            label="Implementation Date"
            type="date"
            value={dates.implementationDate}
            onChange={(v) => setDates((s) => ({ ...s, implementationDate: v }))}
          />
        </div>
      </div>

      {/* 4) Automation Estimation */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Automation Estimation</div>
        <div className={grid3}>
          <Text
            label="Estimate Due Date"
            type="date"
            value={estimation.estimateDueDate}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateDueDate: v }))
            }
          />
          <Text
            label="Estimate Submitted On"
            type="date"
            value={estimation.estimateSubmittedOn}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateSubmittedOn: v }))
            }
          />
          <Select
            label="Estimate Status / OOS"
            value={estimation.estimateStatusOrOOS}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateStatusOrOOS: v }))
            }
            options={estimateStatusOptions}
          />
          <Text
            label="Assigned to / Estimate Done by"
            value={estimation.assignedToOrDoneBy}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, assignedToOrDoneBy: v }))
            }
            placeholder="Name"
          />
          <Text
            label="Estimate Reviewed By"
            value={estimation.estimateReviewedBy}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateReviewedBy: v }))
            }
            placeholder="Name"
          />
          <Select
            label="Func. Automation"
            value={estimation.funcAutomation}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, funcAutomation: v }))
            }
            options={funcAutomationOptions}
          />
          <Area
            label="Reason if OOS / No new Automation"
            value={estimation.reasonIfOOSorNoNew}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, reasonIfOOSorNoNew: v }))
            }
            placeholder="Enter reason"
            disabled={estimation.funcAutomation !== "no"}
          />
          <Text
            label="Total QA Cost (Without Automation)"
            type="number"
            value={estimation.qaCostWithoutAuto}
            
			onChange={(v) =>
			  setEstimation((s) => ({
			    ...s,
			    qaCostWithoutAuto: v,
			    qaCostWithAuto: String(Number(v || 0) + Number(s.automationCost || 0)),
			  }))
			}
			
            placeholder="0"
          />
          <Text
            label="Total QA Cost (With Automation)"
            type="number"
            value={estimation.qaCostWithAuto}
            
			onChange={(v) =>
			  setEstimation((s) => ({
			    ...s,
			    qaCostWithAuto: v,
			    automationCost: String(Number(v || 0) - Number(s.qaCostWithoutAuto || 0)),
			  }))
			}
			
			
            placeholder="0"
          />
          <Text
            label="Targeted Min. Savings"
            type="number"
            value={estimation.targetedMinSavings}
            onChange={() => {}}
            disabled
          />
        </div>
      </div>

      {/* 5) Automation Status */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Automation Status</div>
        <div className={grid2}>
          <Select
            label="Current Automation Status"
            value={automationStatus.currentStatus}
            onChange={(v) =>
              setAutomationStatus((s) => ({ ...s, currentStatus: v }))
            }
            options={automationStatusOptions}
          />
          <Area
            label="Comments"
            value={automationStatus.comments}
            onChange={(v) => setAutomationStatus((s) => ({ ...s, comments: v }))}
            placeholder="Notes, risks, blockers..."
          />
        </div>
      </div>

      {/* 6) QE Deliverables */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>QE Deliverables</div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <Check
            label="Automation Test Plan / LTW"
            value={deliverables.testPlanLTW}
            onChange={(v) => setDeliverables((s) => ({ ...s, testPlanLTW: v }))}
          />
          <Check
            label="QA Checklist followed"
            value={deliverables.qaChecklistFollowed}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, qaChecklistFollowed: v }))
            }
          />
          <Check
            label="Test Case update in ALM"
            value={deliverables.tcUpdateInALMConfluence}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, tcUpdateInALMConfluence: v }))
            }
          />
          <Check
            label="GIT Update"
            value={deliverables.gitUpdate}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, gitUpdate: v }))
            }
          />
          <Check
            label="DSR"
            value={deliverables.dsr}
            onChange={(v) => setDeliverables((s) => ({ ...s, dsr: v }))}
          />
          <Check
            label="LE Sent to PM (Monthly Once)"
            value={deliverables.leSentToPMMonthly}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, leSentToPMMonthly: v }))
            }
          />
          <Check
            label="Master Regression Updated in ALM Library"
            value={deliverables.masterRegUpdatedALM}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, masterRegUpdatedALM: v }))
            }
          />
          <Check
            label="Master Dashboard Updated"
            value={deliverables.masterDashboardUpdated}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, masterDashboardUpdated: v }))
            }
          />
          <Check
            label="Release Handover"
            value={deliverables.releaseHandover}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, releaseHandover: v }))
            }
          />
          <Check
            label="Project Closure Report"
            value={deliverables.projectClosureReport}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, projectClosureReport: v }))
            }
          />
          <Text
            label="ROI Realized in which month"
            type="month"
            value={deliverables.roiRealizedIn}
            onChange={(v) => setDeliverables((s) => ({ ...s, roiRealizedIn: v }))}
          />
          <Check
            label="QE Transformed"
            value={deliverables.qeTransformed}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, qeTransformed: v }))
            }
          />
          <Check
            label="Shift Left followed"
            value={deliverables.shiftLeftFollowed}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, shiftLeftFollowed: v }))
            }
          />
        </div>
      </div>

      {/* 7) Initiatives Planned Usage */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Initiatives Planned Usage</div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          <Check
            label="Conformiq"
            value={false}
            onChange={() => {}}
          />
          <Check
            label="GenAI_PS"
            value={false}
            onChange={() => {}}
          />
          <Check
            label="DDGS_SOA3"
            value={false}
            onChange={() => {}}
          />
          <Check label="E2E" value={false} onChange={() => {}} />
          <Check label="EnvoyAPI" value={false} onChange={() => {}} />
          <Check label="QEDevops" value={false} onChange={() => {}} />
          <Check
            label="Excalibur_phase1"
            value={false}
            onChange={() => {}}
          />
          <Check
            label="Accessibility"
            value={false}
            onChange={() => {}}
          />
          <Check
            label="mMTG_Phase2"
            value={false}
            onChange={() => {}}
          />
          <Check
            label="mmtg TDM"
            value={false}
            onChange={() => {}}
          />
          <Check
            label="Class TDM"
            value={false}
            onChange={() => {}}
          />
        </div>
      </div>
    </div>
  );
}
